content.content:
  1	package com.clothing.service;
  2	
  3	import com.clothing.Database;
  4	import com.clothing.model.*;
  5	import org.slf4j.Logger;
  6	import org.slf4j.LoggerFactory;
  7	
  8	import java.math.BigDecimal;
  9	import java.sql.Connection;
 10	import java.sql.SQLException;
 11	import java.sql.Timestamp;
 12	import java.time.Instant;
 13	import java.util.ArrayList;
 14	import java.util.List;
 15	
 16	public class OrderRepository {
 17	    private static final Logger logger = LoggerFactory.getLogger(OrderRepository.class);
 18	
 19	    public Order createOrder(CheckoutRequest req, Summary summary) {
 20	        try (Connection conn = Database.getConnection()) {
 21	            var stmt = conn.prepareStatement(
 22	                "INSERT INTO orders (customer_cpf, status, products_subtotal, coupon_discount, shipping_cost, " +
 23	                "delivery_days, insurance, payment_adjustment, final_total, club_tier, region, shipping_method, " +
 24	                "payment_method, installments, next_purchase_credit, gift, created_at) " +
 25	                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
 26	                java.sql.Statement.RETURN_GENERATED_KEYS
 27	            );
 28	
 29	            stmt.setString(1, req.customer().cpf());
 30	            stmt.setString(2, OrderStatus.AWAITING_PAYMENT.toString());
 31	            stmt.setBigDecimal(3, summary.productsSubtotal());
 32	            stmt.setBigDecimal(4, summary.couponDiscount());
 33	            stmt.setBigDecimal(5, summary.shippingCost());
 34	            stmt.setInt(6, summary.deliveryDays());
 35	            stmt.setBigDecimal(7, summary.insurance());
 36	            stmt.setBigDecimal(8, summary.paymentAdjustment());
 37	            stmt.setBigDecimal(9, summary.finalTotal());
 38	            stmt.setString(10, req.clubTier().toString());
 39	            stmt.setString(11, req.region().toString());
 40	            stmt.setString(12, req.shippingMethod().toString());
 41	            stmt.setString(13, req.paymentMethod().toString());
 42	            stmt.setInt(14, summary.installments());
 43	            stmt.setBigDecimal(15, summary.nextPurchaseCredit());
 44	            stmt.setBoolean(16, summary.gift());
 45	            stmt.setTimestamp(17, Timestamp.from(Instant.now()));
 46	
 47	            stmt.executeUpdate();
 48	
 49	            var rs = stmt.getGeneratedKeys();
 50	            long orderId = -1;
 51	            if (rs.next()) {
 52	                orderId = rs.getLong(1);
 53	            }
 54	
 55	            for (OrderItem item : req.items()) {
 56	                var itemStmt = conn.prepareStatement(
 57	                    "INSERT INTO order_items (order_id, sku, quantity) VALUES (?, ?, ?)"
 58	                );
 59	                itemStmt.setLong(1, orderId);
 60	                itemStmt.setString(2, item.sku());
 61	                itemStmt.setInt(3, item.quantity());
 62	                itemStmt.executeUpdate();
 63	            }
 64	
 65	            return getOrder(orderId);
 66	        } catch (SQLException e) {
 67	            throw new RuntimeException(e);
 68	        }
 69	    }
 70	
 71	    public Order getOrder(long orderId) {
 72	        try (Connection conn = Database.getConnection()) {
 73	            var stmt = conn.prepareStatement(
 74	                "SELECT id, status, products_subtotal, coupon_discount, shipping_cost, delivery_days, " +
 75	                "insurance, payment_adjustment, final_total, installments, next_purchase_credit, gift, " +
 76	                "tracking_code, created_at FROM orders WHERE id = ?"
 77	            );
 78	            stmt.setLong(1, orderId);
 79	            var rs = stmt.executeQuery();
 80	
 81	            if (!rs.next()) {
 82	                return null;
 83	            }
 84	
 85	            var summary = new Summary(
 86	                new BigDecimal(rs.getString("products_subtotal")),
 87	                new BigDecimal(rs.getString("coupon_discount")),
 88	                new BigDecimal(rs.getString("shipping_cost")),
 89	                rs.getInt("delivery_days"),
 90	                new BigDecimal(rs.getString("insurance")),
 91	                new BigDecimal(rs.getString("payment_adjustment")),
 92	                new BigDecimal(rs.getString("final_total")),
 93	                rs.getInt("installments"),
 94	                Money.divide(new BigDecimal(rs.getString("final_total")), new BigDecimal(rs.getInt("installments"))),
 95	                new BigDecimal(rs.getString("next_purchase_credit")),
 96	                rs.getBoolean("gift")
 97	            );
 98	
 99	            List<OrderItem> items = new ArrayList<>();
100	            var itemStmt = conn.prepareStatement("SELECT sku, quantity FROM order_items WHERE order_id = ?");
101	            itemStmt.setLong(1, orderId);
102	            var itemRs = itemStmt.executeQuery();
103	            while (itemRs.next()) {
104	                items.add(new OrderItem(itemRs.getString("sku"), itemRs.getInt("quantity")));
105	            }
106	
107	            return new Order(
108	                orderId,
109	                OrderStatus.fromString(rs.getString("status")),
110	                rs.getTimestamp("created_at").toInstant(),
111	                summary,
112	                items,
113	                rs.getString("tracking_code")
114	            );
115	        } catch (SQLException e) {
116	            throw new RuntimeException(e);
117	        }
118	    }
119	
120	    public void updateOrderStatus(long orderId, OrderStatus status) {
121	        try (Connection conn = Database.getConnection()) {
122	            var stmt = conn.prepareStatement("UPDATE orders SET status = ? WHERE id = ?");
123	            stmt.setString(1, status.toString());
124	            stmt.setLong(2, orderId);
125	            stmt.executeUpdate();
126	        } catch (SQLException e) {
127	            throw new RuntimeException(e);
128	        }
129	    }
130	
131	    public void updateOrderStatusAndTimestamp(long orderId, OrderStatus status, String timestampColumn) {
132	        try (Connection conn = Database.getConnection()) {
133	            var stmt = conn.prepareStatement(
134	                "UPDATE orders SET status = ?, " + timestampColumn + " = ? WHERE id = ?"
135	            );
136	            stmt.setString(1, status.toString());
137	            stmt.setTimestamp(2, Timestamp.from(Instant.now()));
138	            stmt.setLong(3, orderId);
139	            stmt.executeUpdate();
140	        } catch (SQLException e) {
141	            throw new RuntimeException(e);
142	        }
143	    }
144	
145	    public void setTrackingCode(long orderId, String trackingCode) {
146	        try (Connection conn = Database.getConnection()) {
147	            var stmt = conn.prepareStatement("UPDATE orders SET tracking_code = ? WHERE id = ?");
148	            stmt.setString(1, trackingCode);
149	            stmt.setLong(2, orderId);
150	            stmt.executeUpdate();
151	        } catch (SQLException e) {
152	            throw new RuntimeException(e);
153	        }
154	    }
155	
156	    public void recordPayment(long orderId, String transactionId, Instant paidAt) {
157	        try (Connection conn = Database.getConnection()) {
158	            var stmt = conn.prepareStatement(
159	                "INSERT INTO payment_transactions (order_id, transaction_id, paid_at) VALUES (?, ?, ?)"
160	            );
161	            stmt.setLong(1, orderId);
162	            stmt.setString(2, transactionId);
163	            stmt.setTimestamp(3, Timestamp.from(paidAt));
164	            stmt.executeUpdate();
165	        } catch (SQLException e) {
166	            logger.info("Payment already recorded for order {}", orderId);
167	        }
168	    }
169	
170	    public boolean isPaymentAlreadyRecorded(long orderId, String transactionId) {
171	        try (Connection conn = Database.getConnection()) {
172	            var stmt = conn.prepareStatement(
173	                "SELECT 1 FROM payment_transactions WHERE order_id = ? AND transaction_id = ?"
174	            );
175	            stmt.setLong(1, orderId);
176	            stmt.setString(2, transactionId);
177	            var rs = stmt.executeQuery();
178	            return rs.next();
179	        } catch (SQLException e) {
180	            return false;
181	        }
182	    }
183	
184	    public Instant getOrderCreatedAt(long orderId) {
185	        try (Connection conn = Database.getConnection()) {
186	            var stmt = conn.prepareStatement("SELECT created_at FROM orders WHERE id = ?");
187	            stmt.setLong(1, orderId);
188	            var rs = stmt.executeQuery();
189	            if (rs.next()) {
190	                return rs.getTimestamp("created_at").toInstant();
191	            }
